-- ARTICLE 5: Variable Frequency Drive (VFD) BAS Integration Guide
-----------------------------------------------------------------------
INSERT INTO wiki_articles (category_id, title, slug, summary, content, is_published)
VALUES (
  (SELECT id FROM wiki_categories WHERE slug = 'how-to'),
  'Variable Frequency Drive (VFD) BAS Integration Guide',
  'vfd-bas-integration-guide',
  'Practical guide to integrating variable frequency drives with building automation systems, covering analog and network communication methods, common parameters, and commissioning verification.',
  E'# Variable Frequency Drive (VFD) BAS Integration Guide\n\nVariable frequency drives are among the most commonly integrated devices in building automation. They control fan and pump motor speeds to match load, delivering significant energy savings over constant-speed operation. Integrating VFDs with the BAS enables centralized monitoring, speed commanding, and fault diagnostics.\n\n## Integration Methods\n\n| Method | Signal | Advantages | Disadvantages |\n|---|---|---|---|\n| Analog (0–10 V or 4–20 mA) | Hardwired to controller I/O | Simple, universal, fast | Limited to speed command + 1-2 status points |\n| BACnet/IP or BACnet MS/TP | Network protocol | Full parameter access, diagnostics | Requires BACnet-capable VFD |\n| Modbus RTU or TCP | Network protocol | Wide VFD support, many parameters | Register mapping required |\n| Dry contact (start/stop + speed pot) | Hardwired | Simplest possible integration | No diagnostics, manual speed only |\n\n## Analog Integration\n\n### Wiring\n\nTypical analog integration uses 3–4 wires between the BAS controller and VFD:\n\n| Signal | Direction | Typical Connection |\n|---|---|---|\n| Speed command | Controller to VFD | 0–10 V or 4–20 mA to VFD analog input |\n| Run command | Controller to VFD | Digital output to VFD run terminal |\n| Speed feedback | VFD to Controller | 0–10 V or 4–20 mA from VFD analog output |\n| Run status / fault | VFD to Controller | Relay contact to controller digital input |\n\n### VFD Parameter Setup for Analog Control\n\nCommon VFD parameters to configure (parameter numbers vary by manufacturer):\n\n| Parameter | Setting | Purpose |\n|---|---|---|\n| Control source | Terminal/external | Accept commands from wiring, not keypad |\n| Speed reference source | Analog input | Use analog input for speed setpoint |\n| Analog input type | 0–10 V or 4–20 mA | Match the controller output type |\n| Min frequency | Project-specific (often 15–20 Hz) | Minimum operating speed |\n| Max frequency | Usually 60 Hz (50 Hz in some regions) | Maximum operating speed |\n| Accel time | Project-specific (5–30 seconds typical) | Ramp-up time |\n| Decel time | Project-specific (5–30 seconds typical) | Ramp-down time |\n| Relay output function | Run/fault status | Provide status back to BAS |\n\n### Scaling the Analog Speed Command\n\nThe BAS controller maps a percentage (0–100%) to the analog output:\n\n```\nTypical Scaling:\n  0 V (or 4 mA) = Minimum frequency (e.g., 15 Hz)\n  10 V (or 20 mA) = Maximum frequency (e.g., 60 Hz)\n\nController Output Calculation:\n  Desired Speed: 75%\n  Voltage Output: 0 + (75/100) x 10 = 7.5 V\n  Resulting Frequency: 15 + (75/100) x (60-15) = 48.75 Hz\n```\n\n## Network Integration (BACnet or Modbus)\n\nNetwork integration provides access to many more data points:\n\n### Commonly Available VFD Parameters via Network\n\n| Category | Parameters |\n|---|---|\n| Command | Speed reference, run/stop, direction |\n| Feedback | Output frequency, motor current, motor voltage, power, energy |\n| Status | Running, stopped, fault, warning, at speed |\n| Diagnostics | Fault code, fault history, drive temperature, DC bus voltage |\n| Configuration | Accel/decel times, current limit, motor nameplate data |\n\n### BACnet VFD Integration\n\nBACnet-capable VFDs typically expose:\n\n| BACnet Object | Purpose |\n|---|---|\n| Analog Output (speed reference) | Write speed command |\n| Analog Input (output frequency) | Read actual speed |\n| Analog Input (motor current) | Read motor amps |\n| Analog Input (power) | Read kW consumption |\n| Binary Output (run command) | Start/stop the drive |\n| Binary Input (running status) | Confirm drive is running |\n| Binary Input (fault status) | Fault indication |\n| Multi-State Input (fault code) | Specific fault identification |\n\n### Modbus VFD Integration\n\nFor Modbus integration, obtain the VFD register map from the manufacturer. Key registers typically include:\n\n| Register | Data | Access |\n|---|---|---|\n| Speed reference | Percentage or Hz (scaled) | Read/Write |\n| Control word | Bit-mapped run/stop/direction | Read/Write |\n| Status word | Bit-mapped running/fault/warning | Read Only |\n| Output frequency | Actual Hz (scaled) | Read Only |\n| Motor current | Amps (scaled) | Read Only |\n| Fault code | Numeric fault identifier | Read Only |\n\nRefer to the Modbus register mapping article for detailed integration steps.\n\n## Commissioning Checklist\n\n```\nVFD Integration Commissioning:\n  [ ] Verify motor rotation direction\n  [ ] Confirm minimum speed command produces minimum frequency\n  [ ] Confirm maximum speed command produces maximum frequency\n  [ ] Test intermediate speed command (e.g., 50%) for correct frequency\n  [ ] Verify run command starts the drive\n  [ ] Verify stop command stops the drive\n  [ ] Verify speed feedback reads correctly at BAS\n  [ ] Verify run status reads correctly at BAS\n  [ ] Trigger a fault and verify fault indication at BAS\n  [ ] Clear fault and verify status returns to normal\n  [ ] Confirm Hand-Off-Auto (HOA) switch operation\n  [ ] Test safety interlock (e.g., freezestat, smoke detector)\n  [ ] Verify BAS alarm routing for VFD faults\n  [ ] Record motor nameplate data and VFD settings\n```\n\n## Common Field Issues\n\n| Issue | Cause | Fix |\n|---|---|---|\n| Motor runs at full speed regardless of command | VFD set to keypad control, not terminal | Change control source parameter to terminal/external |\n| Speed reads 0% when drive is running | Feedback wired to wrong terminal or wrong type | Verify analog output terminal and signal type |\n| Drive faults on start | Motor overload, wiring error, or parameter mismatch | Check motor nameplate vs VFD parameters |\n| Drive runs but speed hunts (oscillates) | PID loop fighting BAS PID loop | Disable VFD internal PID if BAS controls speed |\n| Communication drops on Modbus | Baud rate, parity, or address mismatch | Match serial settings between BAS and VFD |\n| BACnet VFD not discovered | Wrong network number or device instance | Check BACnet configuration on VFD |\n| HOA switch in Hand, BAS shows Auto | VFD runs locally but no feedback to BAS | Wire HOA position feedback to BAS digital input |\n\n## Energy Monitoring\n\nVFDs with network integration can provide real-time energy data:\n\n| Parameter | Use |\n|---|---|\n| kW (instantaneous power) | Real-time load monitoring |\n| kWh (accumulated energy) | Energy tracking and cost allocation |\n| Motor current (amps) | Load profiling and predictive maintenance |\n| Output frequency (Hz) | Operating point analysis |\n| Run hours | Maintenance scheduling |\n\nThis data supports energy dashboards, equipment health monitoring, and verification of energy conservation measures.\n\n## References\n\n- ASHRAE Handbook, "HVAC Applications," Chapter 45: "Building Energy Monitoring" (ashrae.org)\n- ASHRAE Guideline 13-2015, "Specifying Direct Digital Control Systems"\n- NEMA Application Guide for AC Adjustable Speed Drive Systems\n- Modbus Organization, "Modbus Application Protocol Specification V1.1b3" (modbus.org)',
  true
)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO wiki_article_facets (article_id, facet_id)
SELECT a.id, f.id
FROM wiki_articles a
CROSS JOIN wiki_facets f
WHERE a.slug = 'vfd-bas-integration-guide'
  AND f.slug IN ('vfd', 'modbus', 'bacnet', 'commissioning', 'integration', 'sensors', 'energy')
