-----------------------------------------------------------------------
-- ARTICLE 6: BAS Trend Data Quality and Retention Strategy
-----------------------------------------------------------------------
INSERT INTO wiki_articles (category_id, title, slug, summary, content, is_published)
VALUES (
  (SELECT id FROM wiki_categories WHERE slug = 'best-practices'),
  'BAS Trend Data Quality and Retention Strategy',
  'bas-trend-data-quality-retention-strategy',
  'Best practices for configuring trend collection intervals, validating data quality, setting retention policies, and avoiding common pitfalls that undermine analytics and reporting.',
  E'# BAS Trend Data Quality and Retention Strategy\n\nTrend data is the foundation of energy analysis, fault detection, commissioning verification, and performance reporting. Poor trend data, whether from misconfigured intervals, missing records, bad sensor readings, or inadequate retention, undermines every downstream use. This guide covers how to get trend collection right.\n\n## Why Trend Data Quality Matters\n\n| Downstream Use | Data Requirement |\n|---|---|\n| Energy analysis | Consistent 15-minute intervals aligned to utility billing |\n| Fault detection and diagnostics (FDD) | Synchronized timestamps across related points |\n| Commissioning verification | Sufficient resolution to see control response |\n| Regulatory reporting (LEED, ENERGY STAR) | Continuous, gap-free records for reporting periods |\n| Predictive maintenance | Long-term baselines for degradation analysis |\n| Occupant complaint resolution | Historical context around the time of complaint |\n\n## Collection Interval Guidelines\n\nMatch the interval to the analytical need, not to the controller''s minimum capability:\n\n| Point Type | Recommended Interval | Rationale |\n|---|---|---|\n| Zone temperature | 15 minutes | Sufficient for comfort analysis; slow-moving variable |\n| Supply/return air temperature | 5 minutes | Needed for control loop analysis |\n| Outdoor air temperature | 15 minutes | Weather correlation; slow-moving |\n| Duct static pressure | 5 minutes | Control loop monitoring |\n| Damper/valve position | 5 minutes | Correlate with temperature trends |\n| Fan/pump speed (VFD) | 5 minutes | Load profiling |\n| Energy meter (kW, kWh) | 15 minutes | Aligns with utility demand intervals |\n| Equipment status (on/off) | Change of Value (COV) | Capture every state change |\n| Setpoints | COV | Only changes are meaningful |\n| CO2 levels | 15 minutes | Ventilation adequacy analysis |\n| Humidity | 15 minutes | Comfort and process monitoring |\n\n### Interval Anti-Patterns\n\n| Anti-Pattern | Problem | Fix |\n|---|---|---|\n| 1-second intervals on all points | Fills storage, overwhelms analytics tools | Use 5 or 15-minute intervals |\n| 1-hour intervals for control points | Cannot see control oscillation or hunting | Use 5-minute intervals |\n| Same interval for all points | Wastes storage on slow points, misses fast ones | Match interval to point dynamics |\n| COV with zero deadband | Records every minor fluctuation | Set deadband to 0.5-1.0 for temperatures, 1-2% for positions |\n\n## Data Quality Checks\n\n### Detecting Common Quality Issues\n\n| Issue | How to Detect | Root Cause |\n|---|---|---|\n| Gaps (missing records) | Plot timeline; look for flat sections or jumps | Controller offline, network loss, storage full |\n| Stuck values (flatline) | Same value repeated for extended period | Sensor failure, broken wire, override in place |\n| Spikes / outliers | Values far outside plausible range | Electrical noise, sensor fault, scaling error |\n| Timestamp drift | Compare controller time to reference | Controller clock not synchronized (NTP) |\n| Duplicate records | Multiple entries for same timestamp | Software bug or misconfigured collection |\n| Units mismatch | Values in wrong range (e.g., deg C in a deg F system) | Incorrect unit configuration |\n\n### Time Synchronization\n\nAll controllers should synchronize clocks via NTP or a BAS time-master:\n\n| Requirement | Target |\n|---|---|\n| Controller clock accuracy | Within 1 second of reference |\n| Synchronization frequency | At least every 4 hours |\n| Protocol | NTP, SNTP, or BACnet TimeSynchronization |\n\nWithout synchronized clocks, correlating trends from different controllers is unreliable.\n\n## Retention Policies\n\n### Tiered Retention\n\nDifferent data ages have different value:\n\n| Tier | Retention | Resolution | Purpose |\n|---|---|---|---|\n| Hot (recent) | 90 days | Full resolution (5 or 15 min) | Active analysis, troubleshooting |\n| Warm (medium-term) | 1–3 years | Hourly or daily averages | Seasonal comparison, M&V |\n| Cold (archive) | 5+ years | Daily or monthly aggregates | Long-term benchmarking, regulatory |\n\n### Storage Estimation\n\nEstimate storage requirements before deployment:\n\n```\nFormula:\n  Daily records per point = (24 hours x 60 min) / interval_minutes\n  Daily storage per point = daily records x bytes per record\n  Total daily storage = points x daily storage per point\n\nExample (1,000 points at 15-minute intervals, 40 bytes per record):\n  Daily records per point: 96\n  Daily storage per point: 96 x 40 = 3,840 bytes\n  Total daily storage: 1,000 x 3,840 = 3.84 MB\n  Annual storage: 3.84 MB x 365 = 1.4 GB\n```\n\n### Platform-Specific Retention Constraints\n\n| Platform | Constraint | Mitigation |\n|---|---|---|\n| JACE-8000 | 2–4 GB storage | Archive to supervisor or external database |\n| Niagara Supervisor | Disk-dependent | Configure ring buffers; archive externally |\n| Metasys (SQL Express) | 10 GB per database | Purge schedule; consider SQL Standard |\n| Cloud platforms | Subscription-dependent | Understand pricing per data point per month |\n\n## Trend Data for Analytics and FDD\n\n### What FDD Tools Need\n\nFault detection and diagnostics tools have specific data requirements:\n\n| Requirement | Detail |\n|---|---|\n| Synchronized timestamps | All related points within the same second |\n| No gaps | Continuous records for analysis windows |\n| Correct units | Engineering units must match the FDD model |\n| Sufficient history | Baseline period (typically 3–12 months) for anomaly detection |\n| Semantic context | Points tagged with equipment and system relationships |\n\n### Data Export Formats\n\n| Format | Use Case |\n|---|---|\n| CSV | Universal; manual analysis in spreadsheets |\n| JSON | API integration; cloud analytics platforms |\n| Haystack (Zinc, JSON) | Semantic-aware analytics tools |\n| SQL database | Direct query from BI and FDD tools |\n| BACnet TrendLog | Native BACnet trend retrieval |\n\n## Maintenance Checklist\n\n| Task | Frequency |\n|---|---|\n| Verify trending is active on all required points | After commissioning and quarterly |\n| Spot-check data quality (gaps, stuck values, outliers) | Monthly |\n| Verify controller clock synchronization | Monthly |\n| Review storage utilization and archive status | Monthly |\n| Validate trend data against reference measurements | Annually |\n| Review and update collection interval settings | Annually |\n| Clean up trends on decommissioned points | As needed |\n\n## References\n\n- ASHRAE Guideline 13-2015, "Specifying Direct Digital Control Systems"\n- ASHRAE Guideline 36-2021, "High-Performance Sequences of Operation for HVAC Systems"\n- ASHRAE Standard 135-2020, Clause 12: "Trending" (BACnet TrendLog object)\n- ENERGY STAR Portfolio Manager Technical Reference (energystar.gov)\n- IPMVP (International Performance Measurement and Verification Protocol), EVO',
  true
)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO wiki_article_facets (article_id, facet_id)
SELECT a.id, f.id
FROM wiki_articles a
CROSS JOIN wiki_facets f
WHERE a.slug = 'bas-trend-data-quality-retention-strategy'
  AND f.slug IN ('trending', 'analytics', 'energy', 'commissioning', 'performance')
ON CONFLICT DO NOTHING;

-- ============================================================
-- Update facet article_count to reflect new articles
-- ============================================================

UPDATE wiki_facets f
SET article_count = COALESCE(counts.cnt, 0)
FROM (
  SELECT facet_id, COUNT(*) as cnt
  FROM wiki_article_facets
  GROUP BY facet_id
) counts
WHERE f.id = counts.facet_id;

UPDATE wiki_facets SET article_count = 0
WHERE id NOT IN (SELECT DISTINCT facet_id FROM wiki_article_facets);
